#!/usr/bin/env bash
# Checks the rules of CONTRIBUTING.md that a machine can check. The Conventions workflow runs it for every
# pull request; it also runs locally:
#
#   check-conventions.sh title   "<pull request title>"
#   check-conventions.sh branch  "<branch name>"
#   check-conventions.sh body    "<pull request description>"
#   check-conventions.sh commits <base> <head>     # ROOT as <base> checks the whole history up to <head>
#
# Exit status 1 means that at least one rule is broken; every broken rule is reported first.
set -uo pipefail

TYPES='feat|fix|perf|refactor|docs|test|build|ci|chore|revert'
TYPE_LIST=${TYPES//|/, }

# The project identity. Every commit has this author, and this committer or GitHub's own web committer
# (the one GitHub puts on a commit it creates, such as the result of "Update branch").
AUTHOR_NAME=${AUTHOR_NAME:-zacala1}
AUTHOR_EMAIL=${AUTHOR_EMAIL:-73224434+zacala1@users.noreply.github.com}
WEB_NAME='GitHub'
WEB_EMAIL='noreply@github.com'

failures=0

fail() {
  failures=$((failures + 1))
  if [ -n "${GITHUB_ACTIONS:-}" ]; then
    echo "::error::$*"
  else
    echo "error: $*" >&2
  fi
}

# <type>(<scope>)?!?: <subject>   with a lowercase subject, at most 72 characters, and no final period
check_header() {
  local label=$1 header=$2
  local re="^(${TYPES})(\([a-z0-9._-]+\))?!?: [a-z0-9].*\$"
  if [[ ! $header =~ $re ]]; then
    fail "$label: \"$header\" must be '<type>(<scope>): <subject>' with a type of ${TYPE_LIST} and a lowercase subject"
    return
  fi
  if ((${#header} > 72)); then
    fail "$label: the first line has ${#header} characters, the limit is 72"
  fi
  if [[ $header == *. ]]; then
    fail "$label: the first line must not end with a period"
  fi
}

# No Co-authored-by line, no "Generated with" / "Generated by" line, no robot emoji.
check_attribution() {
  local label=$1 text=$2
  if grep -qiE '^[[:space:]]*(co-authored-by:|generated (with|by) )' <<<"$text" || grep -qF '🤖' <<<"$text"; then
    fail "$label: remove the Co-authored-by / generated-by line (CONTRIBUTING.md, Author)"
  fi
}

# The description has the two sections of .github/pull_request_template.md, each with some text under it.
check_sections() {
  local label=$1 text=${2//$'\r'/} section
  for section in Summary Verification; do
    if ! awk -v s="$section" '
      $0 ~ "^##[ \t]+" s "[ \t]*$" { in_section = 1; next }
      /^##[ \t]/ { in_section = 0 }
      in_section && /[^ \t]/ { found = 1 }
      END { exit !found }' <<<"$text"; then
      fail "$label: needs a '## $section' section with text under it (see .github/pull_request_template.md)"
    fi
  done
}

check_branch() {
  local name=$1
  local re="^(${TYPES})/[a-z0-9][a-z0-9._-]*\$"
  if [[ ! $name =~ $re ]]; then
    fail "branch \"$name\" must be '<type>/<topic>' with a type of ${TYPE_LIST} and a lowercase topic, for example feat/ack-queue"
  fi
}

check_commits() {
  local base=$1 head=$2 range sha short an ae cn ce parents
  if [ "$base" = ROOT ]; then range=$head; else range="$base..$head"; fi
  local shas
  mapfile -t shas < <(git rev-list --reverse "$range")
  if [ "${#shas[@]}" -eq 0 ]; then
    echo "no commits to check in $range"
    return
  fi
  for sha in "${shas[@]}"; do
    short=${sha:0:7}
    IFS='|' read -r an ae cn ce parents <<<"$(git log -1 --format='%an|%ae|%cn|%ce|%P' "$sha")"
    if [ "$an" != "$AUTHOR_NAME" ] || [ "$ae" != "$AUTHOR_EMAIL" ]; then
      fail "$short: the author is '$an <$ae>', it must be '$AUTHOR_NAME <$AUTHOR_EMAIL>'"
    fi
    if { [ "$cn" != "$AUTHOR_NAME" ] || [ "$ce" != "$AUTHOR_EMAIL" ]; } &&
      { [ "$cn" != "$WEB_NAME" ] || [ "$ce" != "$WEB_EMAIL" ]; }; then
      fail "$short: the committer is '$cn <$ce>', it must be '$AUTHOR_NAME <$AUTHOR_EMAIL>'"
    fi
    # A merge commit (for example from "Update branch") has no conventional subject.
    if [[ $parents == *" "* ]]; then
      continue
    fi
    check_header "$short" "$(git log -1 --format=%s "$sha")"
    check_attribution "$short" "$(git log -1 --format=%b "$sha")"
  done
}

usage() {
  sed -n '2,11p' "$0" | sed 's/^# \{0,1\}//' >&2
  exit 2
}

[ $# -ge 1 ] || usage
mode=$1
shift
case "$mode" in
  title)
    [ $# -eq 1 ] || usage
    check_header "pull request title" "$1"
    ;;
  branch)
    [ $# -eq 1 ] || usage
    check_branch "$1"
    ;;
  body)
    [ $# -le 1 ] || usage
    check_sections "pull request description" "${1:-}"
    check_attribution "pull request description" "${1:-}"
    ;;
  commits)
    [ $# -eq 2 ] || usage
    check_commits "$1" "$2"
    ;;
  *)
    usage
    ;;
esac

if [ "$failures" -gt 0 ]; then
  echo "$failures rule(s) broken. The rules are in CONTRIBUTING.md." >&2
  if [ "$mode" = commits ]; then
    echo "To change the author of the commits of a branch:" >&2
    echo "  git config user.name \"$AUTHOR_NAME\" && git config user.email \"$AUTHOR_EMAIL\"" >&2
    echo "  git rebase origin/main --exec 'git commit --amend --no-edit --reset-author'" >&2
  fi
  exit 1
fi
echo "ok: $mode"
